// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;

import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * The probe deadline is enforced purely by cooperative polling, so every interpreted cursor loop that can advance a
 * data-proportional number of times without emitting a row must poll. These tests pin that contract for the row-plan
 * cursor layer: a pre-tripped deadline scope must abort each loop within a bounded number of source rows instead of
 * letting the loop run its input dry (the HC:10 probe hang of 2026-08-18 was a FilterCursor rejecting rows for minutes
 * with the deadline scope active and no poll ever reached).
 */
class LmdbNativeRowPlanPollPointTest {

	/**
	 * More rows than any masked poll interval; small enough that an un-polled loop finishes quickly (test fails red, it
	 * does not hang).
	 */
	private static final int SOURCE_ROWS = 1 << 20;

	/** The poll mask is 1024; allow a few intervals of slack before calling the loop unbounded. */
	private static final int POLL_BOUND = 4096;

	@Test
	void filterCursorHonoursTrippedDeadlineWhileRejectingEveryRow() throws Exception {
		BoundedTrueCursor source = new BoundedTrueCursor(SOURCE_ROWS);
		FilterCursor cursor = new FilterCursor(source, row -> false, null);
		try (LmdbNativeProbeDeadline.Scope scope = LmdbNativeProbeDeadline.enter(System.nanoTime() - 1L)) {
			assertThrows(LmdbNativeProbeDeadlineExceeded.class, cursor::next,
					"a rejecting filter must poll the deadline instead of draining its input");
		}
		assertTrue(source.calls <= POLL_BOUND,
				"deadline fired only after " + source.calls + " source rows (bound " + POLL_BOUND + ")");
	}

	@Test
	void minusCursorHonoursTrippedDeadlineWhileRemovingEveryLeftRow() throws Exception {
		NativeSlotLayout layout = layout(2);
		RowState row = row(layout);
		ValuesRow leftRow = new ValuesRow(new int[] { 0 }, new long[] { 7L });
		ValuesRow[] leftRows = new ValuesRow[SOURCE_ROWS];
		Arrays.fill(leftRows, leftRow);
		CountingValuesCursor left = new CountingValuesCursor(leftRows, row);
		SlotPlan right = new ValuesPlan(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 7L }) });
		MinusCursor cursor = new MinusCursor(left, right, 1L, row);
		try (LmdbNativeProbeDeadline.Scope scope = LmdbNativeProbeDeadline.enter(System.nanoTime() - 1L)) {
			assertThrows(LmdbNativeProbeDeadlineExceeded.class, cursor::next,
					"a MINUS that removes every left row must poll the deadline instead of draining the left side");
		}
		assertTrue(left.calls <= POLL_BOUND,
				"deadline fired only after " + left.calls + " left rows (bound " + POLL_BOUND + ")");
	}

	@Test
	void distinctCursorHonoursTrippedDeadlineWhileSkippingDuplicates() throws Exception {
		NativeSlotLayout layout = layout(1);
		RowState row = row(layout);
		ValuesRow duplicate = new ValuesRow(new int[] { 0 }, new long[] { 5L });
		ValuesRow[] rows = new ValuesRow[SOURCE_ROWS];
		Arrays.fill(rows, duplicate);
		SlotPlan distinct = new RowDistinctPlan(new ValuesPlan(rows), new int[] { 0 });
		RowCursor cursor = distinct.open(row);
		assertTrue(cursor.next(), "the first row is unique and must be emitted");
		try (LmdbNativeProbeDeadline.Scope scope = LmdbNativeProbeDeadline.enter(System.nanoTime() - 1L)) {
			assertThrows(LmdbNativeProbeDeadlineExceeded.class, cursor::next,
					"a DISTINCT skipping duplicates must poll the deadline instead of draining its input");
		}
	}

	@Test
	void pollingIsInertWithoutAnActiveDeadlineScope() throws Exception {
		BoundedTrueCursor source = new BoundedTrueCursor(SOURCE_ROWS);
		FilterCursor cursor = new FilterCursor(source, row -> false, null);
		assertTrue(!cursor.next(), "without a scope the filter drains its input and reports exhaustion");
		assertTrue(source.calls > SOURCE_ROWS, "the whole input was consumed");
	}

	private static NativeSlotLayout layout(int slots) {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		for (int slot = 0; slot < slots; slot++) {
			names.put("v" + slot, slot);
		}
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		return layout;
	}

	private static RowState row(NativeSlotLayout layout) {
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		return row;
	}

	/** Emits {@code limit} rows that bind nothing, then reports exhaustion; counts how far it was driven. */
	private static final class BoundedTrueCursor implements RowCursor {
		final int limit;
		int calls;

		BoundedTrueCursor(int limit) {
			this.limit = limit;
		}

		@Override
		public boolean next() {
			return calls++ < limit;
		}

		@Override
		public void close() {
		}
	}

	/** A ValuesCursor that counts how many rows the consumer pulled. */
	private static final class CountingValuesCursor implements RowCursor {
		final ValuesCursor delegate;
		int calls;

		CountingValuesCursor(ValuesRow[] rows, RowState row) {
			this.delegate = new ValuesCursor(rows, row);
		}

		@Override
		public boolean next() {
			calls++;
			return delegate.next();
		}

		@Override
		public void close() {
			delegate.close();
		}
	}
}
